function segmentIsActive(segment: string, today: Date) {
  const dateMatches = segment.match(/20\d{2}[-/.]\d{1,2}[-/.]\d{1,2}/gu) ?? [];
  if (dateMatches.length === 0) return true;
  return dateMatches.some((value) => {
    const [year, month, day] = value.split(/[-/.]/u).map(Number);
    const deadline = new Date(year, month - 1, day);
    return deadline >= today;
  });
}

export function isExcelCampusCompanyActive(company: HotCompany, now = new Date()) {
  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const deadlineText = company.deadlineText?.trim();
  if (!deadlineText) return true;
  return deadlineText.split(/[;；]/u).some((segment) => segmentIsActive(segment.trim(), today));
}

export const EXCEL_CAMPUS_COMPANIES = EXCEL_CAMPUS_COMPANIES_ALL.filter((company) => isExcelCampusCompanyActive(company));
